import{c as e,Q as a,j as s,m as r}from"./chunks/framework.BqPkuuVc.js";const o="/assets/edit-event-starts.BAu_LkDL.png",n="/assets/docs-setup-formats-start-times-class-mass-start.BQ2l5h3N.png",i="/assets/docs-setup-formats-start-times-class-exclude.C_epHrjy.png",h="/assets/competitors-edit-allocated-start-time.Chj-UQWv.png",l="/assets/dashboard-quick-actions-punching-start.Dsh4_pJh.png",d="/assets/competitors-edit-result-no-start-time.CELI9im5.png",c="/assets/docs-setup-formats-start-times-shift-dialog.BPF64Hms.png",b=JSON.parse('{"title":"Start times","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/start-times.md","filePath":"user/event-setup/start-times.md"}'),m={name:"user/event-setup/start-times.md"};function g(u,t,f,p,w,v){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="start-times" tabindex="-1">Start times <a class="header-anchor" href="#start-times" aria-label="Permalink to &quot;Start times&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers allocating start times to competitors.</p><p>A competitor&#39;s <em>start time</em> is the clock time their race is measured from — their <em>race time</em> is simply finish minus start. This page explains where a start time can come from, how Manager decides which one to use when there&#39;s more than one, and what happens when you change a start time after competitors are already running.</p><blockquote><p><strong>Note:</strong> This page is about the <em>rules</em> — the sources of a start time and which one wins. The <strong>start draw</strong> (the tool that spaces individual start times at a regular interval and randomises the order) has its own page: <a href="./start-draw">Drawing start times</a>.</p></blockquote><h2 id="which-kind-of-start-do-you-mean" tabindex="-1">Which kind of start do you mean? <a class="header-anchor" href="#which-kind-of-start-do-you-mean" aria-label="Permalink to &quot;Which kind of start do you mean?&quot;">​</a></h2><p>&quot;Start&quot; covers several different things in orienteering, and Manager handles each in a different place. Find yours here:</p><table tabindex="0"><thead><tr><th>You want…</th><th>What Manager calls it</th><th>Where</th></tr></thead><tbody><tr><td>Each runner to leave at their own time from a start list</td><td>Individual allocated start</td><td><a href="#individual-start-times">Individual start times</a> and <a href="./start-draw">Drawing start times</a></td></tr><tr><td>Everyone to start together</td><td>Event mass start</td><td><a href="#event-mass-start">Event mass start</a></td></tr><tr><td>One class, or a group of classes, to start together — waves</td><td>Class mass start</td><td><a href="#class-mass-start">Class mass start</a></td></tr><tr><td>Runners to start whenever they&#39;re ready, timed from the start punch</td><td>Punched start</td><td><a href="#punched-starts">Punched starts</a></td></tr><tr><td>Two or more start locations on the map, each used by some courses</td><td>Several Start controls</td><td><a href="#more-than-one-start-location">More than one start location</a></td></tr><tr><td>Several start units at one start — spares, or one per lane — perhaps on different codes</td><td>Several Start codes</td><td><a href="#several-start-units">Several start units</a></td></tr><tr><td>Several start lanes, each sending runners off at the same times</td><td>Lanes in the draw</td><td><a href="./start-draw#the-core-idea-lanes">The core idea: lanes</a></td></tr><tr><td>Some runners in a class to start from a different place</td><td>A different course for them</td><td><a href="#more-than-one-start-location">More than one start location</a></td></tr><tr><td>Blocks of the start window shared out between clubs or groups</td><td>Start blocks</td><td><a href="./start-draw#start-blocks">Start blocks</a></td></tr><tr><td>An early, late, or together/apart start for one runner</td><td>Start request</td><td><a href="./start-draw#honouring-start-requests">Honouring start requests</a></td></tr><tr><td>Day 2 of a carnival to start in order of the overall standings</td><td>Chasing start</td><td><a href="./multi-stage-events#chasing-starts">Chasing starts</a></td></tr><tr><td>Waiting relay runners sent out together</td><td>Restart</td><td><a href="./relay-events#restarts-omstart">Restarts (omstart)</a></td></tr><tr><td>The course to start at its first numbered control, with no start unit</td><td>First control</td><td><a href="./classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a></td></tr><tr><td>Two events sharing a start on one day</td><td>Start window</td><td><a href="./../running-the-event/two-events-at-once#starts-at-different-times-start-windows">Starts at different times: start windows</a></td></tr><tr><td>The whole start delayed, or brought forward</td><td>Move all start times</td><td><a href="#moving-every-start-time">Moving every start time</a></td></tr></tbody></table><p>These combine. A typical event might have two start locations, two lanes at each, a drawn start list, and a mass start for the beginners&#39; class.</p><h2 id="the-four-sources-of-a-start-time" tabindex="-1">The four sources of a start time <a class="header-anchor" href="#the-four-sources-of-a-start-time" aria-label="Permalink to &quot;The four sources of a start time&quot;">​</a></h2><p>A start time can come from any of four places:</p><table tabindex="0"><thead><tr><th>Source</th><th>Where it&#39;s set</th><th>Applies to</th></tr></thead><tbody><tr><td><strong>Individual allocated start</strong></td><td>The <a href="./start-draw">start draw</a>, an <a href="./import-event-data#start-list-iof-startlist-xml">import</a>, or the competitor&#39;s <strong><a href="./competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog</td><td>One competitor</td></tr><tr><td><strong>Class mass start</strong></td><td><strong>Edit Class</strong> dialog → <em>Start time</em> section</td><td>Everyone in a class</td></tr><tr><td><strong>Event mass start</strong></td><td><strong><a href="./create-event#editing-event-details">Event details</a></strong> → <strong>Starts</strong> tab</td><td>Everyone in the event</td></tr><tr><td><strong>Punched start</strong></td><td>The competitor punches a Start unit on the day</td><td>One competitor</td></tr></tbody></table><p>The first three are <em>allocated</em> — times you set in advance. The fourth is <em>punched</em> — recorded live when the competitor starts. They interact through a simple hierarchy.</p><blockquote><p><strong>Note:</strong> Above all four sits a correction: a <strong>start time override</strong> on the competitor&#39;s <strong>Overrides</strong> tab beats every one of them. It&#39;s for putting right one runner&#39;s start after the fact, not for planning starts — see <a href="./../running-the-event/resolving-issues#a-start-that-was-interrupted">A start that was interrupted</a> and <a href="./../reference/status-and-race-time#how-race-time-is-calculated">How race time is calculated</a>.</p></blockquote><h2 id="which-start-time-wins-the-hierarchy" tabindex="-1">Which start time wins: the hierarchy <a class="header-anchor" href="#which-start-time-wins-the-hierarchy" aria-label="Permalink to &quot;Which start time wins: the hierarchy&quot;">​</a></h2><p>For the <strong>allocated</strong> start time, the most specific level always beats the more general one:</p><ol><li><strong>Individual allocated start</strong> (highest priority)</li><li><strong>Class mass start</strong></li><li><strong>Event mass start</strong> (lowest priority)</li></ol><p>A competitor uses the highest level that&#39;s set for them. Someone with their own allocated time ignores any class or event mass start; someone with no individual time but whose class has a mass start uses that; otherwise they fall back to the event mass start (if the event has one and their class isn&#39;t excluded from it). If none of the three is set, the competitor has no allocated start — their time will come from a punch, or not at all.</p><p><strong>Example — a mass start event with two exceptions.</strong> Most of the field runs an event mass start at <strong>11:00</strong>, except the <em>Junior</em> class, which sets off as an earlier wave (a class mass start at <strong>10:45</strong>), and one course-checker, <em>Pat</em>, given an individual start of <strong>09:30</strong> to get round before the crowd:</p><table tabindex="0"><thead><tr><th>Competitor</th><th>Most specific setting they have</th><th>Start they get</th><th>Why</th></tr></thead><tbody><tr><td>Most of the field</td><td>Event mass start only</td><td><strong>11:00</strong></td><td>Nothing more specific is set</td></tr><tr><td>Anyone in <em>Junior</em></td><td>Class mass start (10:45)</td><td><strong>10:45</strong></td><td>Class mass start overrides the event mass start</td></tr><tr><td>Pat</td><td>Individual start (09:30)</td><td><strong>09:30</strong></td><td>An individual start overrides both mass starts</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Whether a <strong>punched start</strong> beats the allocated time is a separate question, decided by the <em>punching-start override</em> rather than the hierarchy. See <a href="#punched-starts">Punched starts</a> below.</p></blockquote><p>Manager resolves all of this for you automatically — you don&#39;t compute it by hand. To see where a competitor&#39;s time came from, look beside it: the <strong>Competitors</strong> list marks a mass-start time <em>(class)</em> or <em>(event)</em>, and an individual time <em>(individual)</em> where a mass start would otherwise have applied; the <strong><a href="./competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog names the source after the start time — <em>allocated start</em>, <em>class mass start</em>, <em>event mass start</em>, <em>start punch</em>, or <em>check punch</em> when Manager had to fall back to one.</p><h2 id="event-mass-start" tabindex="-1">Event mass start <a class="header-anchor" href="#event-mass-start" aria-label="Permalink to &quot;Event mass start&quot;">​</a></h2><p>Use an event mass start when <strong>everyone starts together</strong> at one time.</p><p>Open the event dashboard, click the <strong>Event details</strong> button at the top of the dashboard (see <a href="./create-event#editing-event-details">Editing event details</a>), and go to the <strong>Starts</strong> tab. Switch on <strong>Mass start</strong> and set the <strong>Mass start time</strong>. Every competitor whose class doesn&#39;t override it picks up this time.</p><p>The same tab holds <strong>Allow punching starts to override allocated starts</strong> (see <a href="#punched-starts">Punched starts</a>), <strong>Time runners with no start from check punch or midnight</strong> (see <a href="#a-runner-with-no-start-time">A runner with no start time</a>) and <strong>Start window</strong>. A start window is only needed when two events share a day and the same Start and Check unit numbers and this one has punching starts — see <a href="./create-event#starts">Starts</a> and <a href="./../running-the-event/two-events-at-once#starts-at-different-times-start-windows">Starts at different times: start windows</a>.</p><p><img src="'+o+'" alt="The Starts tab of Event details with Mass start on and a Mass start time of 10:00:00, Start window off, Allow punching starts to override allocated starts on, and Time runners with no start from check punch or midnight on Use global setting"></p><blockquote><p><strong>Note:</strong> A relay event has a <strong>Relay</strong> tab in place of <strong>Starts</strong>, and relay classes work differently: every leg is timed from the class&#39;s mass start (or the event&#39;s), an individual start time on a leg runner is never used, and start punches never apply. See <a href="./relay-events">Relay events</a>.</p></blockquote><h2 id="class-mass-start" tabindex="-1">Class mass start <a class="header-anchor" href="#class-mass-start" aria-label="Permalink to &quot;Class mass start&quot;">​</a></h2><p>Use a class mass start when <strong>one class starts together</strong> but the rest of the event doesn&#39;t — for example a beginners&#39; class that all sets off at once.</p><p>Open the <strong>Edit Class</strong> dialog (click the class on the <strong>Classes</strong> page), and in the <em>Start time</em> section switch on <strong>Class mass start</strong> and set the <strong>Class mass start time</strong>. A class mass start overrides the event mass start for that class, and is in turn overridden by any individual allocated time a competitor in the class has.</p><p><img src="'+n+'" alt="Edit class for Beginner, scrolled to its Start time section: Class mass start switched on with a Class mass start time of 10:45:00"></p><p>Two related controls in the same dialog:</p><ul><li><strong>Exclude this class from event mass start</strong> — shown only when the event has a mass start and this class has no class mass start of its own. Tick it to make the class start <em>individually</em> despite the event-wide mass start. (A class mass start already implies this, so the toggle only appears when there&#39;s no class mass start to make the point moot.)</li></ul><p><img src="'+i+'" alt="Edit class for M21E in an event with a mass start: Class mass start off, and Exclude this class from event mass start switched on"></p><p><strong>Example — <em>Elite</em> opts out of the mass start.</strong> Your event has a mass start at <strong>10:00</strong> for the casual classes, but you want <em>Elite</em> to run individual drawn times instead. Tick <strong>Exclude this class from event mass start</strong> on Elite and run the <a href="./start-draw">draw</a> for it: Elite competitors get their drawn times, while everyone else still goes at 10:00.</p><blockquote><p><strong>Tip — running waves:</strong> Manager has no separate &quot;wave start&quot; feature, and it doesn&#39;t need one. To start groups in waves, give each class (or group of classes) its own <strong>class mass start</strong> at a staggered time — 10:00 for the first wave, 10:15 for the next, and so on. Each wave is just a class mass start at a different time.</p></blockquote><p>See <a href="./classes-and-courses">Classes and courses</a> for the full Edit Class dialog.</p><h2 id="individual-start-times" tabindex="-1">Individual start times <a class="header-anchor" href="#individual-start-times" aria-label="Permalink to &quot;Individual start times&quot;">​</a></h2><p>Individual allocated times sit at the top of the hierarchy, so they override any class or event mass start for that competitor. They reach Manager several ways:</p><ul><li><strong>The start draw</strong> — the usual way to produce a full individual start list. It spaces times at an interval and randomises the order. See <a href="./start-draw">Drawing start times</a>.</li><li><strong>Import</strong> — an <a href="./import-event-data#start-list-iof-startlist-xml">IOF StartList file</a>, an Eventor sync, or a CSV entry list can carry start times, which land as individual allocated times. See <a href="./import-event-data">Importing event data</a>.</li><li><strong>By hand</strong> — open a competitor&#39;s <strong>Edit competitor</strong> dialog and go to its <strong>Start</strong> tab. The <strong>Allocated start time</strong> field shows their individual time, and is empty when they have none; the <strong>Event mass start</strong> and <strong>Class mass start</strong> that would otherwise apply are listed above it for reference. Set, change, or clear the time here. The time field is a <strong>24-hour clock</strong> with seconds (so 1 pm is <code>13:00:00</code>). (Relay leg runners have no <strong>Start</strong> tab — their start comes from the team.) The tab also holds the competitor&#39;s <strong>Start request</strong> — an early or late start, or a start near or away from others — which the draw can honour; see <a href="./start-draw#honouring-start-requests">Honouring start requests</a>.</li></ul><p><img src="'+h+'" alt="The Start tab of Edit competitor: the Event mass start and Class mass start that would apply (both not set), the Allocated start time field, the On start punch dropdown beside it with the sentence saying which time is used, and the Start request picker"></p><ul><li><strong>Many at once</strong> — <strong>Competitors → Actions → Bulk edit…</strong> has <strong>Allocated start time</strong> and <strong>On start punch</strong> columns, and either can be set for every row shown at once. See <a href="./competitors-clubs-teams#editing-many-competitors-at-once">Editing many competitors at once</a>.</li><li><strong>A chasing start</strong> — on a later day of a carnival, the multi-stage event&#39;s <strong>Chasing starts</strong> tab writes each competitor&#39;s start from their gap behind the leader, as an ordinary individual allocated time. See <a href="./multi-stage-events#chasing-starts">Chasing starts</a>.</li><li><strong>A late entry</strong> — give them a free slot by hand; see <a href="./../running-the-event/late-entries#giving-them-a-start-time">Giving them a start time</a>.</li></ul><p>Once the event has been started and a competitor&#39;s start time passes, Manager automatically marks them <strong>On course</strong> even before any punch arrives — which is what the <a href="./../running-the-event/safety-check">safety check</a> relies on to know who&#39;s out in the forest.</p><h2 id="punched-starts" tabindex="-1">Punched starts <a class="header-anchor" href="#punched-starts" aria-label="Permalink to &quot;Punched starts&quot;">​</a></h2><p>At many events competitors start by punching a <strong>Start</strong> unit rather than to a fixed clock time. That punch is the <em>punched start</em>. It&#39;s how you run a <strong>start-when-ready</strong> event: don&#39;t allocate any times at all, and each competitor&#39;s start punch becomes their start time.</p><p>When a competitor has <em>both</em> an allocated time <em>and</em> a punched start, the <strong>punching-start override</strong> decides which wins. (When only one of the two exists, that one is always used — the override only matters when they disagree.) The override is set at three levels, most specific winning:</p><ol><li><strong>Per competitor</strong> — the <strong>On start punch</strong> dropdown beside the <strong>Allocated start time</strong> on the competitor&#39;s <strong>Start</strong> tab, with three choices. It appears only once the competitor has an allocated time of some kind, since with nothing to conflict with there&#39;s nothing to choose: <ul><li><strong>Use event default</strong> — defer to the event setting (the default). The option says what that currently means, as in <em>Use event default (punch not allowed)</em>.</li><li><strong>Always use allocated start</strong> — ignore any start punch for this competitor.</li><li><strong>Allow punching start</strong> — the start punch wins; the allocated time is the fallback if no punch is recorded.</li></ul></li><li><strong>Per event</strong> — <strong>Allow punching starts to override allocated starts</strong> on the event&#39;s <strong>Starts</strong> tab. Applies to every competitor who&#39;s left on <em>Use event default</em>.</li><li><strong>New-event default</strong> — <strong>Punching starts override allocated starts</strong> on the global <a href="./../reference/settings">Settings</a> page, copied into each new event.</li></ol><p>The competitor dialog spells out the live result in plain language beneath the dropdown — for example <em>&quot;Start punch at 10:23:14 is used. Allocated start of 10:22:00 is the fallback.&quot;</em> or <em>&quot;Start time of 10:22:00 is used. Start punch at 10:23:14 is ignored.&quot;</em> — so you can confirm at a glance which time the competitor will be timed from.</p><p><strong>Example — late to the start.</strong> Your event leaves <strong>Allow punching starts to override allocated starts</strong> off, so allocated times win. <em>Robin</em> was drawn to start at <strong>10:14</strong> but was late to the start and was allowed to do a punching start at <strong>10:16:03</strong>:</p><ul><li>With the override off (the default here), Robin is timed from the drawn <strong>10:14</strong> — the two extra minutes are Robin&#39;s loss, exactly as a fixed start list intends.</li><li>Robin was late to the start through no fault of their own, so you open their <strong><a href="./competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog and set <strong>On start punch</strong> to <strong>Allow punching start</strong>. Now Robin is timed from the <strong>10:16:03</strong> punch, and 10:14 is kept only as a fallback in case no punch had been recorded.</li><li>Quicker at the download desk: select Robin in the dashboard&#39;s <strong>Quick competitor actions</strong> tile and click <strong>Allow punching start</strong>. It sets the same choice. The button is only there when it would change something — the event&#39;s allocated times win, Robin is still on <strong>Use event default</strong>, and Robin is not running a relay leg — and it goes once Robin has it. To take it back, use the dialog.</li></ul><p><img src="'+l+'" alt="The dashboard&#39;s Quick actions tile with a competitor selected, showing an Allow punching start button under the card number and class"></p><p>(If Robin had <em>no</em> allocated time at all — a start-when-ready event — the override wouldn&#39;t come into it: with nothing to conflict with, the punch is simply the start.)</p><p><strong>Example — out before their start.</strong> Same event, allocated times still win. <em>Sam</em> is a volunteer drawn to start at <strong>11:00</strong> who goes out early, before their shift, punching the Start unit at <strong>09:20</strong> and finishing at <strong>10:30</strong>:</p><ul><li>Timed from 11:00, Sam would finish before starting — no race time, so <strong>DNF</strong>. Manager doesn&#39;t do that. A start punch <em>earlier</em> than a competitor&#39;s own allocated time is when they really started, whatever the event setting says, so Sam is timed from the <strong>09:20</strong> punch — <strong>1:10:00</strong> — and Sam&#39;s <strong>On start punch</strong> is switched to <strong>Allow punching start</strong> for you, so the dialog shows why.</li><li>To time Sam from 11:00 after all, set <strong>On start punch</strong> to <strong>Always use allocated start</strong>, or back to <strong>Use event default (punch not allowed)</strong>. Either is your decision, and Manager never switches it back — not when Sam&#39;s card is read again, and not for any later start punch. (Sam, back at 10:30, would then have no race time and a <strong>DNF</strong>; that is the result you have chosen.)</li><li>If the 09:20 punch turns out to be someone else&#39;s — Sam was entered on the wrong card number — correcting Sam&#39;s card takes that start away and puts <strong>On start punch</strong> back to <strong>Use event default</strong> too, unless you had chosen a setting for Sam yourself. Sam is timed from 11:00 again, or from Sam&#39;s own start punch if that was early as well.</li></ul><p>This only applies to an <em>individual</em> allocated time, not a class or event mass start: mass-start runners don&#39;t punch a Start, so a start punch on their card is almost always left over from a previous run on a card that wasn&#39;t cleared. For the same reason Manager won&#39;t treat a card&#39;s start punch as an early start when it records a different day from the card&#39;s finish, or comes before the card&#39;s check punch.</p><p>Punched starts arrive when a card is read (see <a href="./../running-the-event/card-download">Downloading cards</a>) or via a radio Start control.</p><blockquote><p><strong>Tip:</strong> The punch doesn&#39;t have to be at a Start unit. Set a course&#39;s <strong>Start</strong> to <strong>First control</strong> and a punch at the course&#39;s first, ordinary numbered control is its start punch, under the same rules — useful when the start unit was left behind. See <a href="./classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</p></blockquote><h2 id="a-runner-with-no-start-time" tabindex="-1">A runner with no start time <a class="header-anchor" href="#a-runner-with-no-start-time" aria-label="Permalink to &quot;A runner with no start time&quot;">​</a></h2><p>Sometimes a finisher reaches none of the sources above: no allocated time, no start punch, and no start override — the Start unit failed, or they didn&#39;t punch it. By default Manager times them from their check punch, or from midnight when there isn&#39;t one, which places them on a time nobody measured. Turn that fallback off — the setting is called <strong>Time runners with no start from check punch or midnight</strong> — and they&#39;re <strong>Not competing</strong> until you give them a start instead, with the reason shown at the download desk and on the competitor.</p><p><img src="'+d+'" alt="Edit competitor on its Result tab with the status Not competing set automatically, and the note: Not competing because there&#39;s no start time. They completed the course, but there&#39;s no start punch or allocated start time."></p><p>The setting is in <strong>Settings → <a href="./../reference/settings#event-defaults">Event defaults</a></strong>, and each event can choose otherwise on its <strong>Starts</strong> tab (<strong>Use global setting</strong>, <strong>On for this event</strong>, <strong>Off for this event</strong>). See <a href="./../reference/status-and-race-time#a-runner-with-no-start-time">A runner with no start time</a> for exactly what each answer does.</p><p>To give one such runner the start they really had, add a start time override on their <strong>Overrides</strong> tab, or, with the fallback off, use the download desk&#39;s <strong>Give them a start time</strong> panel — see <a href="./../running-the-event/card-download#fast-fixes-right-after-a-download">Fast fixes right after a download</a>.</p><h2 id="more-than-one-start-location" tabindex="-1">More than one start location <a class="header-anchor" href="#more-than-one-start-location" aria-label="Permalink to &quot;More than one start location&quot;">​</a></h2><p>A start location belongs to a <strong>course</strong>, not to a class. Each start on the map is a <strong>Start control</strong> in Manager, and each course picks the Start it runs from in <strong>Edit course</strong>. Classes share the start of the course they run.</p><ol><li>Add a Start control for each location: <strong>Controls → Add control</strong>, type <strong>Start</strong>. They&#39;re numbered <code>Start</code>, <code>Start 2</code>, … and you can rename them (&quot;Start North&quot;, &quot;Start 2 – 1.2 km&quot;) on the <strong>Name</strong> tab of <strong>Edit control</strong>. See <a href="./controls-and-radio-controls#multiple-start-finish-and-check-controls">Multiple Start, Finish and Check controls</a>.</li><li>In <strong>Edit course</strong> for each course, choose its <strong>Start</strong>. A course file from Purple Pen, OCAD or Condes that has two starts imports with each course already on the right one.</li></ol><p>What the course&#39;s Start decides:</p><ul><li><strong>The first leg.</strong> The leg from the Start to control 1 is measured from that start, for leg lengths and the <a href="./event-map-and-radio-placement">event map</a>.</li><li><strong>The clock correction.</strong> A <strong>Time offset</strong> on a Start control corrects the start punches of every competitor whose course starts there — the competitor&#39;s start is corrected by <em>their course&#39;s</em> Start, whichever unit they punched.</li><li><strong>Nothing in the draw&#39;s shared-first-control check.</strong> The draw compares first controls only, and doesn&#39;t know where the starts are on the ground. Two courses from different starts that go to the same first control are treated as sharing a first leg: with <strong>Separate lanes sharing a first control</strong> on (the default), the draw moves one lane out of the other&#39;s way. If the two starts are far apart, switch that setting off and ignore the warning, or click <strong>Allocate anyway</strong> — see <a href="./start-draw#lanes-that-share-a-first-control">Lanes that share a first control</a>.</li></ul><p>What it does <strong>not</strong> decide:</p><ul><li><strong>Which unit counts as the start punch.</strong> A punch at <em>any</em> Start unit is a start punch — the card records it as a start, and a radio punch on any of the event&#39;s <strong>Start codes</strong> is one. A runner who goes to the wrong start is still timed from the start they punched; Manager doesn&#39;t flag it.</li><li><strong>Start times.</strong> The start time hierarchy above is the same at every start. Use a class or event mass start, or the draw, as usual. Starts at different locations can run at different times: give their classes different mass starts, or different first starts in the draw (each course is its own lane).</li></ul><p><strong>Some runners in one class at a different start.</strong> Make them a separate class on a course from the other start — for example <em>M35</em> and <em>M35 (Start 2)</em>. A class can hold more than one course (a <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">course pool</a>) and results will be right, but two things follow the class&#39;s <em>first</em> course: the draw lays the whole class out in that course&#39;s lane, and the start punch takes that course&#39;s Start time offset. Neither is wrong while both starts have no offset and the class isn&#39;t drawn — otherwise use separate classes.</p><p><strong>On the day:</strong></p><ul><li><strong>The start list.</strong> The <strong>Start list</strong> tab groups by <strong>Course</strong>, which is effectively by start when each start has its own courses. Filter it to the classes using one start to print a list for that start&#39;s team. See <a href="./start-draw#the-start-list-tab">The Start list tab</a>.</li><li><strong>Info screens.</strong> Set the <a href="./../screens/info-screens#starters-at-one-start">Starters</a> screen at each start to that start, and it shows only the runners leaving from there. The starters under a <a href="./../screens/info-screens#start-clock">Start clock</a> show every start, with each runner&#39;s class and course on their card.</li><li><strong>Station memory.</strong> When you read start units to find non-starters, read <strong>every</strong> start&#39;s unit (or every check unit) before you click <strong>Mark as DNS</strong>. After reading only one, the runners from the other start are still on the <strong>No record of starting</strong> list. See <a href="./../running-the-event/station-memory#who-is-accounted-for">Who is accounted for</a>.</li></ul><h2 id="several-start-units" tabindex="-1">Several start units <a class="header-anchor" href="#several-start-units" aria-label="Permalink to &quot;Several start units&quot;">​</a></h2><p>Many starts have more than one Start unit: one per lane, a spare beside the first, or one at each start location. Manager doesn&#39;t need to know how many there are, or which is which.</p><ul><li><strong>Card downloads</strong> need nothing. The card records the punch as a start, whatever code the unit was programmed with.</li><li><strong>Radio start punches</strong> need every Start unit&#39;s code listed under <strong>Start codes</strong> on the event&#39;s <strong>Radio controls</strong> tab — <code>1, 11</code> for two units, for example. A code that isn&#39;t listed is read as a course control, and the runner doesn&#39;t appear to start. See <a href="./controls-and-radio-controls#start-finish-and-check-codes">Start, Finish and Check codes</a>.</li><li><strong>Clocks.</strong> A Time offset belongs to the Start <em>control</em>, not to a unit, so every unit at one start shares one correction. Set every unit&#39;s clock before the event on the <a href="./../running-the-event/station-memory#the-station-clock">SportIdent station</a> screen rather than correcting one unit afterwards.</li><li><strong>Station memory.</strong> Read every Start unit, not just one, before marking non-starters (see above).</li></ul><p>You don&#39;t need one Start control per unit. Add a second Start control only for a second <strong>location</strong> that some courses run from.</p><h2 id="when-you-change-a-start-time" tabindex="-1">When you change a start time <a class="header-anchor" href="#when-you-change-a-start-time" aria-label="Permalink to &quot;When you change a start time&quot;">​</a></h2><p>Start-time settings stay editable throughout the event, and Manager re-applies changes automatically — there&#39;s no recompute button. A change to the event mass start, a class mass start, an individual allocation, or an override flows through to the affected competitors within a few seconds.</p><p>What that means in practice:</p><ul><li><strong>Changing one level moves only the competitors who use it.</strong> Each competitor&#39;s start comes from a single source in the <a href="#which-start-time-wins-the-hierarchy">hierarchy</a>, so a change reaches just those competitors. In the mass-start example above, nudging the 11:00 event mass start to 11:10 would move most of the field — but leave <em>Junior</em> (on its 10:45 class mass start) and <em>Pat</em> (on a 09:30 individual start) exactly where they are.</li><li><strong>Race times are recalculated for anyone already finished.</strong> Changing a start time is usually a <em>correction</em>, so Manager re-times finished competitors against the new start rather than ignoring the change.</li><li><strong>A start later than the finish has no valid race time.</strong> If a change would put a competitor&#39;s start <em>after</em> their finish punch, their race time can&#39;t be computed and Manager sets them to <strong>DNF</strong>. Watch for this if you push a morning class to an afternoon mass start after they&#39;ve already run.</li></ul><p>For working through a specific competitor whose time looks wrong, see <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</p><h2 id="moving-every-start-time" tabindex="-1">Moving every start time <a class="header-anchor" href="#moving-every-start-time" aria-label="Permalink to &quot;Moving every start time&quot;">​</a></h2><p>The courses aren&#39;t ready and the morning has to go back a quarter of an hour. Or bad weather is forecast for the afternoon and the whole thing comes forward an hour. Rather than editing each level by hand, open the <strong>Start list</strong> tab of <strong>Starts</strong>, choose <strong>Actions → Move all start times…</strong>, pick <strong>Later</strong> or <strong>Earlier</strong> and how far — minutes and seconds, so half a start interval is as easy to ask for as a quarter of an hour.</p><p>Every <strong>individual allocated start time</strong> moves by that amount, together with the first start times on the <a href="./start-draw">Manage starts</a> screen — so a later single-lane re-draw doesn&#39;t put that lane back where it was.</p><p><strong>Mass starts are left alone.</strong> A class mass start, the event mass start and a relay&#39;s restart time all stay exactly where you put them. A mass start is a moment fixed for a whole class or the whole field — usually published, and often shared with something outside Manager — so moving one is a separate decision you make on the class or in the event details. If you want a mass start to move too, change it there afterwards.</p><p>The <strong>course closure time</strong> is left alone for the same sort of reason. Closure is about daylight and when the forest has to be clear, not about when the field goes out — pulling the starts forward an hour doesn&#39;t mean you want everyone back an hour early. Change it yourself in the event settings if you do.</p><p>The dialog shows where the first start ends up before you commit, and how much of the event moves with it.</p><p><img src="'+c+'" alt="The Move all start times dialog: Later selected, 15 minutes and 0 seconds, First start now 10:00:00, First start after the move 10:15:00, and Moves 67 competitors with start times, with Cancel and Move"></p><p><strong>When you can do this.</strong> While the event is still in <strong>setup</strong>, whenever you like. Once it has been started, only while every start is still ahead of the clock — as soon as the first competitor has gone, the morning isn&#39;t yours to rewrite any more, and the option refuses with a note saying so. A mass start counts here even though it never moves: if a class has been sent off, the door is shut. Move one class on the Manage starts screen, or one competitor&#39;s time, instead.</p><p><strong>Start lists you&#39;ve already given out won&#39;t move.</strong> Anything printed or published before the change shows the old times, so reprint and re-publish afterwards.</p><h2 id="printing-and-publishing-the-start-list" tabindex="-1">Printing and publishing the start list <a class="header-anchor" href="#printing-and-publishing-the-start-list" aria-label="Permalink to &quot;Printing and publishing the start list&quot;">​</a></h2><p>The <strong>Start list</strong> tab of <strong>Starts</strong> is the start list as you&#39;d hand it out: grouped by class or course, with PDF, print, IOF XML, Orienteering JSON and CSV exports and a direct upload to Eventor, all under its <strong>Actions</strong> menu. Every one of them publishes the <em>allocated</em> start — individual, else the class mass start, else the event&#39;s — never a punched one. See <a href="./start-draw#the-start-list-tab">The Start list tab</a>.</p><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>24-hour clock.</strong> The time picker has no AM/PM — afternoon starts are <code>13:00:00</code>, <code>14:30:00</code>, and so on.</li><li><strong>A mass start that doesn&#39;t move everyone.</strong> If some competitors don&#39;t pick up the mass start you just set, they almost certainly have an <em>individual</em> allocated time (from an earlier draw or import) that overrides it — individual always wins. Clear those individual times if you want the mass start to apply. The <a href="./start-draw#classes-that-start-together-aren-t-drawn">start draw</a> counts them for you: it leaves a mass-start class out of the draw and says how many of its entrants still hold a start of their own.</li><li><strong>A class that&#39;s excluded — or not.</strong> A class with <strong>Exclude this class from event mass start</strong> ticked won&#39;t inherit the event mass start; a class you <em>expected</em> to start individually but didn&#39;t exclude will pick it up. Check the toggle when a class&#39;s start times surprise you.</li><li><strong>Punching override set the wrong way.</strong> Allocated times being ignored (or punches being ignored) usually traces back to the punching-start override — check the event&#39;s <strong>Starts</strong> tab and the competitor&#39;s <strong>On start punch</strong> choice.</li><li><strong>Start after finish.</strong> Setting a start time later than someone&#39;s finish drops them to DNF (see above).</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./start-draw">Drawing start times</a> — the tool that allocates individual start times in bulk, and where a single class or competitor is moved</li><li><a href="./controls-and-radio-controls#multiple-start-finish-and-check-controls">Controls and radio controls</a> — adding Start controls for more start locations, and the Start codes for radio start units</li><li><a href="./../running-the-event/station-memory">Station memory</a> — reading every start unit to find the non-starters</li><li><a href="./classes-and-courses">Classes and courses</a> — setting class mass starts and the event-mass-start exclude toggle</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — editing a single competitor&#39;s allocated start</li><li><a href="./import-event-data#start-list-iof-startlist-xml">Importing event data</a> — bringing start times in from a start-list file or Eventor</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — how a start time feeds into status and race time</li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a> — fixing a competitor whose start time is wrong</li><li><a href="./relay-events">Relay events</a> — mass starts, restarts and why a relay leg never takes a punched start</li><li><a href="./../running-the-event/late-entries#giving-them-a-start-time">Late entries</a> — giving someone entered on the day a start time</li><li><a href="./multi-stage-events#chasing-starts">Multi-stage events</a> — chasing (pursuit) starts for a later day of a carnival</li></ul>',96)])])}const S=e(m,[["render",g]]);export{b as __pageData,S as default};
